CREATE SCHEMA aether_access;
CREATE TABLE aether_access.schema_state(singleton boolean PRIMARY KEY CHECK(singleton),version integer NOT NULL,checksum text NOT NULL);
CREATE TABLE aether_access.organizations(tenant text NOT NULL,id text NOT NULL,PRIMARY KEY(tenant,id));
CREATE TABLE aether_access.members(tenant text NOT NULL,organization text NOT NULL,user_id text NOT NULL,role text NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(tenant,organization,user_id),FOREIGN KEY(tenant,organization) REFERENCES aether_access.organizations(tenant,id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.enrolled(tenant text NOT NULL,user_id text NOT NULL,PRIMARY KEY(tenant,user_id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.workspaces(tenant text NOT NULL,id text NOT NULL,organization text NOT NULL,is_default boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant,id),UNIQUE(tenant,organization,id),FOREIGN KEY(tenant,organization) REFERENCES aether_access.organizations(tenant,id));
CREATE UNIQUE INDEX one_default_workspace ON aether_access.workspaces(tenant,organization) WHERE is_default;
CREATE TABLE aether_access.workspace_members(tenant text NOT NULL,workspace text NOT NULL,user_id text NOT NULL,role text NOT NULL CHECK(role IN ('owner','editor','viewer')),PRIMARY KEY(tenant,workspace,user_id),FOREIGN KEY(tenant,workspace) REFERENCES aether_access.workspaces(tenant,id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.resources(tenant text NOT NULL,id text NOT NULL,organization text NOT NULL,workspace text,parent text,owner text NOT NULL,kind text NOT NULL CHECK(kind IN ('document','folder')),app text NOT NULL,trashed boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant,id),FOREIGN KEY(tenant,organization) REFERENCES aether_access.organizations(tenant,id),FOREIGN KEY(tenant,organization,workspace) REFERENCES aether_access.workspaces(tenant,organization,id),FOREIGN KEY(tenant,parent) REFERENCES aether_access.resources(tenant,id),FOREIGN KEY(tenant,owner) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.grants(tenant text NOT NULL,resource text NOT NULL,user_id text NOT NULL,role text NOT NULL CHECK(role IN ('owner','editor','viewer')),PRIMARY KEY(tenant,resource,user_id),FOREIGN KEY(tenant,resource) REFERENCES aether_access.resources(tenant,id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
-- Only previously redeemed, active links confer access. Token issuance/redemption
-- remains a separate route; never infer a visit from a client-supplied link id.
CREATE TABLE aether_access.links(tenant text NOT NULL,id text NOT NULL,resource text NOT NULL,role text NOT NULL CHECK(role IN ('editor','viewer')),expires timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant,id),FOREIGN KEY(tenant,resource) REFERENCES aether_access.resources(tenant,id));
CREATE TABLE aether_access.link_visits(tenant text NOT NULL,link text NOT NULL,user_id text NOT NULL,PRIMARY KEY(tenant,link,user_id),FOREIGN KEY(tenant,link) REFERENCES aether_access.links(tenant,id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.applications(tenant text NOT NULL,id text NOT NULL,enabled boolean NOT NULL,restricted boolean NOT NULL,PRIMARY KEY(tenant,id));
CREATE TABLE aether_access.teams(tenant text NOT NULL,id text NOT NULL,PRIMARY KEY(tenant,id));
CREATE TABLE aether_access.team_members(tenant text NOT NULL,team text NOT NULL,user_id text NOT NULL,PRIMARY KEY(tenant,team,user_id),FOREIGN KEY(tenant,team) REFERENCES aether_access.teams(tenant,id),FOREIGN KEY(tenant,user_id) REFERENCES aether_identity.users(tenant,id));
CREATE TABLE aether_access.team_apps(tenant text NOT NULL,team text NOT NULL,app text NOT NULL,PRIMARY KEY(tenant,team,app),FOREIGN KEY(tenant,team) REFERENCES aether_access.teams(tenant,id),FOREIGN KEY(tenant,app) REFERENCES aether_access.applications(tenant,id));
CREATE TABLE aether_access.audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant text NOT NULL,actor text NOT NULL,action text NOT NULL,target text NOT NULL,happened_at timestamptz NOT NULL DEFAULT clock_timestamp());
